echo "Waiting for you to collect payment on an order..."
echo "Press Enter after you've clicked 'Collect Payment' button"
read

echo ""
echo "Checking backend logs for [PRINT] messages..."
echo "================================================"

# Get recent backend logs
if [ -f /tmp/backend.log ]; then
    tail -50 /tmp/backend.log | grep -E "\[PRINT\]|ERROR.*print|print.*error" -i
else
    echo "No backend log file found at /tmp/backend.log"
    echo "Checking process output instead..."
fi

echo ""
echo "Checking print jobs in database..."
echo "================================================"

cd backend
MONGODB_URI="mongodb://admin:password123@localhost:27017/cafe_pos?replicaSet=rs0&authSource=admin" \
MONGODB_DATABASE="cafe_pos" \
go run cmd/check-print-jobs/main.go

echo ""
echo "If no print jobs found, check:"
echo "1. Order status changed to PAID?"
echo "2. Backend logs show [PRINT] messages?"
echo "3. Any errors in backend logs?"
